{
  "items": [
    {
      "name": "Polynomial.hasseDeriv",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → ℕ → Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "Polynomial.hasseDeriv_monomial",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k n : ℕ) (r : R),\n  (Polynomial.hasseDeriv k) ((Polynomial.monomial n) r) = (Polynomial.monomial (n - k)) (↑(n.choose k) * r)"
    },
    {
      "name": "Polynomial.hasseDeriv_apply",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ) (f : Polynomial R),\n  (Polynomial.hasseDeriv k) f = f.sum fun i r => (Polynomial.monomial (i - k)) (↑(i.choose k) * r)"
    },
    {
      "name": "Polynomial.hasseDeriv_comp",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k l : ℕ),\n  Polynomial.hasseDeriv k ∘ₗ Polynomial.hasseDeriv l = (k + l).choose k • Polynomial.hasseDeriv (k + l)"
    },
    {
      "name": "Polynomial.hasseDeriv_coeff",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ) (f : Polynomial R) (n : ℕ),\n  ((Polynomial.hasseDeriv k) f).coeff n = ↑((n + k).choose k) * f.coeff (n + k)"
    },
    {
      "name": "LaurentSeries.hasseDeriv_single",
      "module_name": "Mathlib.RingTheory.LaurentSeries",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {V : Type u_2} [inst_1 : AddCommGroup V] [inst_2 : Module R V] (k : ℕ) (n : ℤ)\n  (x : V), (LaurentSeries.hasseDeriv R k) ((HahnSeries.single n) x) = (HahnSeries.single (n - ↑k)) (Ring.choose n k • x)"
    },
    {
      "name": "MvPolynomial.pderiv_monomial",
      "module_name": "Mathlib.Algebra.MvPolynomial.PDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type v} {a : R} {s : σ →₀ ℕ} [inst : CommSemiring R] {i : σ},\n  (MvPolynomial.pderiv i) ((MvPolynomial.monomial s) a) = (MvPolynomial.monomial (s - Finsupp.single i 1)) (a * ↑(s i))"
    },
    {
      "name": "MvPolynomial.mkDerivation_monomial",
      "module_name": "Mathlib.Algebra.MvPolynomial.Derivation",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} (R : Type u_2) {A : Type u_3} [inst : CommSemiring R] [inst_1 : AddCommMonoid A] [inst_2 : Module R A]\n  [inst_3 : Module (MvPolynomial σ R) A] [inst_4 : IsScalarTower R (MvPolynomial σ R) A] (f : σ → A) (s : σ →₀ ℕ)\n  (r : R),\n  (MvPolynomial.mkDerivation R f) ((MvPolynomial.monomial s) r) =\n    r • s.sum fun i k => (MvPolynomial.monomial (s - Finsupp.single i 1)) ↑k • f i"
    },
    {
      "name": "Polynomial.taylor_coeff",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (r : R) (f : Polynomial R) (n : ℕ),\n  ((Polynomial.taylor r) f).coeff n = Polynomial.eval r ((Polynomial.hasseDeriv n) f)"
    },
    {
      "name": "MvPolynomial.pderiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.PDeriv",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type v} → [inst : CommSemiring R] → σ → Derivation R (MvPolynomial σ R) (MvPolynomial σ R)"
    }
  ]
}

{
