    {
      "name": "Finsupp.lapply",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.Defs",
      "kind": "definition",
      "type": "{α : Type u_1} →\n  {M : Type u_2} →\n    {R : Type u_5} → [inst : Semiring R] → [inst_1 : AddCommMonoid M] → [inst_2 : Module R M] → α → (α →₀ M) →ₗ[R] M"
    },
    {
      "name": "Finsupp.lhom_ext",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} {N : Type u_3} {R : Type u_5} {R₂ : Type u_6} [inst : Semiring R] [inst_1 : Semiring R₂]\n  [inst_2 : AddCommMonoid M] [inst_3 : Module R M] [inst_4 : AddCommMonoid N] [inst_5 : Module R₂ N] {σ₁₂ : R →+* R₂}\n  ⦃φ ψ : (α →₀ M) →ₛₗ[σ₁₂] N⦄, (∀ (a : α) (b : M), φ (Finsupp.single a b) = ψ (Finsupp.single a b)) → φ = ψ"
    },
    {
      "name": "Finsupp.lsum_comp_lsingle",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LSum",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} {N : Type u_3} {R : Type u_5} {R₂ : Type u_6} (S : Type u_8) [inst : Semiring R]\n  [inst_1 : Semiring R₂] [inst_2 : Semiring S] [inst_3 : AddCommMonoid M] [inst_4 : Module R M]\n  [inst_5 : AddCommMonoid N] [inst_6 : Module R₂ N] {σ : R →+* R₂} [inst_7 : Module S N] [inst_8 : SMulCommClass R₂ S N]\n  (f : α → M →ₛₗ[σ] N) (i : α), (Finsupp.lsum S) f ∘ₛₗ Finsupp.lsingle i = f i"
    },
    {
      "name": "DFinsupp.lmk",
      "module_name": "Mathlib.LinearAlgebra.DFinsupp",
      "kind": "definition",
      "type": "{ι : Type u_1} →\n  {R : Type u_3} →\n    {M : ι → Type u_5} →\n      [inst : Semiring R] →\n        [inst_1 : (i : ι) → AddCommMonoid (M i)] →\n          [inst_2 : (i : ι) → Module R (M i)] →\n            [DecidableEq ι] → (s : Finset ι) → ((i : ↑↑s) → M ↑i) →ₗ[R] Π₀ (i : ι), M i"
    },
    {
      "name": "DFinsupp.lsum_single",
      "module_name": "Mathlib.LinearAlgebra.DFinsupp",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {R : Type u_3} (S : Type u_4) {M : ι → Type u_5} {N : Type u_6} [inst : Semiring R]\n  [inst_1 : (i : ι) → AddCommMonoid (M i)] [inst_2 : (i : ι) → Module R (M i)] [inst_3 : AddCommMonoid N]\n  [inst_4 : Module R N] [inst_5 : DecidableEq ι] [inst_6 : Semiring S] [inst_7 : Module S N]\n  [inst_8 : SMulCommClass R S N] (F : (i : ι) → M i →ₗ[R] N) (i : ι) (x : M i),\n  ((DFinsupp.lsum S) F) (DFinsupp.single i x) = (F i) x"
    }
  ]
}

